// Assign incremental stable IDs to ensure exactly 288 accessible items
export const ISL_DATASET_WORDS: DatasetWordItem[] = RAW_VOCABULARY.map((w, index) => ({
  id: `isl-token-${String(index + 1).padStart(3, '0')}`,
  ...w,
}));
